const res = $input.first().json;
const built = $('Decision: build WhatsApp').first().json;
const tpl = ($env.OFFICE_WA_TEMPLATE || '').trim();
const approvalTpl = ($env.OFFICE_WA_APPROVAL_TEMPLATE || '').trim();
